// go: github.com/microsoft/TypeScript/tsc/internal/ls.RenameInfo 3012d88b
class RenameInfo(
    @kotlin.jvm.JvmField var canRename: Boolean = false,
    @kotlin.jvm.JvmField var localizedErrorMessage: String = "",
    @kotlin.jvm.JvmField var displayName: String = "",
    @kotlin.jvm.JvmField var triggerSpan: Range = Range(),
    @get:kotlin.jvm.JvmName("goGet_fileToRename") @set:kotlin.jvm.JvmName("goSet_fileToRename") var fileToRename: RootedPath = RootedPath(""),
    @get:kotlin.jvm.JvmName("goGet_newFileName") @set:kotlin.jvm.JvmName("goSet_newFileName") var newFileName: RootedPath = RootedPath(""),
) {

    fun goCopy(): RenameInfo = RenameInfo(canRename = canRename, localizedErrorMessage = localizedErrorMessage, displayName = displayName, triggerSpan = triggerSpan.goCopy(), fileToRename = fileToRename, newFileName = newFileName)

    fun goSet(o: RenameInfo) {
        canRename = o.canRename
        localizedErrorMessage = o.localizedErrorMessage
        displayName = o.displayName
        triggerSpan = o.triggerSpan.goCopy()
        fileToRename = o.fileToRename
        newFileName = o.newFileName
